In hashing there is a hash function that maps keys to some values. But these hashing functions may lead to a collision that is two or more keys are mapped to same value. Chain hashing avoids collision. The idea is to make each cell of hash table point to a linked list of records that have same hash function value.For a more detailed explanation and theoretical background on this approach, please refer to Hashing | Set 2 (Separate Chaining).Let's create a hash function, such that our hash table has 'n' number of buckets. To insert a node into the hash table, we first compute the hash index for the given key using a hash function:hashIndex = key % noOfBuckets.This index determines the appropriate bucket where the node should be inserted.Example: noOfBuckets = 7keys to insert = [15, 11, 27, 8]For each key:15 % 7 = 111 % 7 = 427 % 7 = 68  % 7 = 1Insert: Move to the bucket corresponding to the above-calculated hash index and insert the new node at the end of the list.Delete: To delete a node from hash table, calculate the hash index for the key, move to the bucket corresponding to the calculated hash index, and search the list in the current bucket to find and remove the node with the given key (if found).   Table of ContentSimple ChainingChaining with RehashingSimple ChainingThis method has not concept of rehashing. It only has a fixed size array i.e. fixed numbers of buckets.Try It Yourself
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Hash {
    // Number of buckets
    int bucketCount;
    vector<vector<int>> table;

public:
    // Constructor to initialize the hash 
    // table with given bucket count
    Hash(int buckets) {
        bucketCount = buckets;
        table.resize(bucketCount);
    }

    // Function to insert a key into hash table
    void insert(int key) {
        // Get the hash index for the key
        int index = getHashIndex(key);

        // Insert the key into the corresponding bucket
        table[index].push_back(key);
    }

    // Function to delete a key from hash table
    void remove(int key) {
        // Get the hash index for the key
        int index = getHashIndex(key);

        // Find and remove the key from the bucket
        auto it = find(table[index].begin(), table[index].end(), key);

        // Erase the key if found
        if (it != table[index].end()) {
            table[index].erase(it);
        }
    }

    // Function to display the hash table
    void display() {
        for (int i = 0; i < bucketCount; i++) {
            cout << i;

            // Print all keys in current bucket
            for (int key : table[i]) {
                cout << " --> " << key;
            }

            cout << endl;
        }
    }

private:
    // Simple hash function to map key to index
    int getHashIndex(int key) {
        return key % bucketCount;
    }
};

int main() {
    vector<int> keys = {7, 18, 12, 25};

    Hash hashTable(7);

    for (int key : keys) {
        hashTable.insert(key);
    }

    hashTable.remove(12);

    hashTable.display();

    return 0;
}


